/**
 * api.js - API Service for ATHENA Frontend
 * Handles all HTTP requests to FastAPI backend
 * Week 2 - Days 10-14
 */

import axios from 'axios';

// API base URL - Change this when deploying
const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

// Create axios instance with default config
const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 30000, // 30 second timeout
});

// Request interceptor (optional - for adding auth tokens, etc.)
api.interceptors.request.use(
  (config) => {
    console.log(`API Request: ${config.method.toUpperCase()} ${config.url}`);
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor (optional - for error handling)
api.interceptors.response.use(
  (response) => {
    console.log(`API Response: ${response.status}`, response.data);
    return response;
  },
  (error) => {
    console.error('API Error:', error.response?.data || error.message);
    return Promise.reject(error);
  }
);

/**
 * Get API root information
 */
export const getRoot = async () => {
  const response = await api.get('/');
  return response.data;
};

/**
 * Check API health status
 */
export const getHealth = async () => {
  const response = await api.get('/health');
  return response.data;
};

/**
 * Get list of supported stocks
 */
export const getSupportedStocks = async () => {
  const response = await api.get('/stocks');
  return response.data;
};

/**
 * Make stock price prediction
 * @param {string} ticker - Stock ticker symbol (e.g., 'AAPL')
 * @returns {Promise<Object>} Prediction result with explanations
 */
export const predictStock = async (ticker) => {
  const response = await api.post('/predict', { ticker });
  return response.data;
};

export default api;
